1	import { promises as fs } from "fs";
2	import path from "path";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge } from "@/components/ui/primitives";
5	import { renderMarkdown } from "@/lib/markdown";
6	import { DocsViewer, type DocSection } from "@/components/admin/DocsViewer";
7	
8	export const dynamic = "force-dynamic";
9	
10	/**
11	 * Private, admin-only view of the platform documentation. Reads
12	 * docs/DOCUMENTATION.md straight off disk (server-side) and renders it with a
13	 * small in-house safe Markdown renderer — the public /docs page is retired.
14	 */
15	export default async function AdminDocs() {
16	  await requireArea("platform");
17	
18	  let raw = "";
19	  let error: string | null = null;
20	  try {
21	    raw = await fs.readFile(path.join(process.cwd(), "docs", "DOCUMENTATION.md"), "utf8");
22	  } catch {
23	    error = "docs/DOCUMENTATION.md could not be read from disk.";
24	  }
25	
26	  // Split into searchable sections at each H2 heading; everything before the
27	  // first H2 is the intro section.
28	  const sections: DocSection[] = [];
29	  if (raw) {
30	    const lines = raw.replace(/\r\n/g, "\n").split("\n");
31	    let title = "Overview";
32	    let buf: string[] = [];
33	    let idx = 0;
34	    const push = () => {
35	      const body = buf.join("\n").trim();
36	      if (!body && sections.length > 0) return;
37	      sections.push({
38	        id: `sec-${idx++}`,
39	        title,
40	        html: renderMarkdown(body),
41	        search: `${title}\n${body}`.toLowerCase(),
42	      });
43	    };
44	    for (const line of lines) {
45	      const h2 = line.match(/^##\s+(.*)$/);
46	      if (h2) {
47	        push();
48	        buf = [line];
49	        title = h2[1].trim();
50	      } else {
51	        buf.push(line);
52	      }
53	    }
54	    push();
55	  }
56	
57	  return (
58	    <div className="space-y-6">
59	      <PageHeader title="Documentation" sub="Internal platform documentation — private to staff.">
60	        <Badge tone="brand">{sections.length} sections</Badge>
61	      </PageHeader>
62	
63	      {error ? (
64	        <div className="card py-12 text-center text-sm text-red-300">{error}</div>
65	      ) : (
66	        <DocsViewer sections={sections} />
67	      )}
68	    </div>
69	  );
70	}
