/**
 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
 * is built from, so the whole site reads as one designed thing.
 *
 *  - <Section>   full-width band with an alternating background "tone" and a
 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
 *                optional visual). Replaces ~10 hand-rolled hero blocks.
 *  - <Eyebrow>   the uppercase tag above a heading.
 *  - <SectionTitle> heading + optional sub, centered or left.
 *
 * Colors and animations are the existing brand system (navy + violet/blue).
 */

type Tone = "base" | "panel" | "deep" | "light";
type Size = "sm" | "md" | "lg";

const TONE: Record<Tone, string> = {
  base: "",
  panel: "tone-panel",
  deep: "tone-deep",
  light: "tone-light",
};
const PAD: Record<Size, string> = {
  sm: "py-14 sm:py-16",
  md: "py-20 sm:py-24",
  lg: "py-24 sm:py-32",
};

/** A full-width section band. `tone` alternates the background for rhythm. */
export function Section({
  children,
  tone = "base",
  size = "md",
  id,
  className = "",
}: {
  children: React.ReactNode;
  tone?: Tone;
  size?: Size;
  id?: string;
  className?: string;
}) {
  return (
    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
      <div className="rail">{children}</div>
    </section>
  );
}

/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
}

/** Section heading block: eyebrow + title + optional sub. */
