"use client";

/**
 * PREVIEW TEMPLATE — redesigned game-mods page.
 *
 * A far more premium take on the live /game-servers/mods page, keeping its
 * HONEST framing: Nxeon sells REAL access (SFTP + file manager + live console),
 * not a magic universal installer. Signature elements:
 *   • an asymmetric hero with an animated File-Manager panel (a plugin upload
 *     progress-fills, then flips to "restart to load") — the real access, shown
 *   • a visual 3-step "how modding works on your server" flow (upload → drop → restart)
 *   • a category-driven grid of mod/plugin types (icons + example chips, not walls)
 *   • per-game showcases on real key art, with the real modding platform + folder
 *   • a "no walled garden" trust strip, compact reviews, and a deploy CTA
 *
 * Net-new, preview-only. Reuses the shared gamelanding kit + pv-* CSS. Touches
 * no live page or shared component.
 */

import Link from "next/link";
import { useState } from "react";
import type { ModsContent, IconName, GameShowcase } from "./data";
import { usePrefersReducedMotion, useInViewOnce, useCountUp } from "@/components/marketing/gamelanding/kit";
import { GameLogo } from "@/components/marketing/GameLogo";
import {
  IconBolt,
  IconApps,
  IconTerminal,
  IconUsers,
  IconScale,
  IconGauge,
  IconShield,
  IconDisk,
  IconLock,
  IconCode,
  IconSpark,
  IconGift,
  IconServer,
  IconNetwork,
  IconCheck,
  IconArrow,
} from "@/components/marketing/icons";

const ACCENT = "#8a70fb"; // brand-400 — the page's spine colour
const CYAN = "#22d3ee";

const ICONS: Record<IconName, (p: { size?: number; className?: string }) => React.ReactElement> = {
  bolt: IconBolt,
  apps: IconApps,
  terminal: IconTerminal,
  users: IconUsers,
  scale: IconScale,
  gauge: IconGauge,
  shield: IconShield,
  disk: IconDisk,
  lock: IconLock,
  code: IconCode,
  spark: IconSpark,
  gift: IconGift,
  server: IconServer,
  network: IconNetwork,
};

/* ── animated File-Manager panel (the "real access", visualised) ─────────── */
function FileManagerPanel() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const pct = useCountUp(100, seen, 2200, reduced);
  const done = pct >= 100;

  return (
    <div ref={ref} className="relative">
      {/* ambient glow */}
      <div
        className={`pointer-events-none absolute -inset-6 -z-10 rounded-[2rem] blur-3xl ${reduced ? "" : "pv-glow-breathe"}`}
        style={{ background: `radial-gradient(60% 60% at 60% 30%, ${ACCENT}30, transparent 70%)` }}
        aria-hidden
      />
      <div className={`relative overflow-hidden rounded-2xl border border-white/10 bg-navy-900/80 shadow-2xl backdrop-blur-md ${reduced ? "" : "pv-float-slow"}`}>
        {/* title bar */}
        <div className="flex items-center gap-2 border-b border-white/[0.07] bg-white/[0.03] px-4 py-3">
          <span className="flex gap-1.5" aria-hidden>
            <span className="h-2.5 w-2.5 rounded-full bg-red-400/70" />
            <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
            <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
          </span>
          <span className="ml-2 flex items-center gap-2 font-mono text-[11px] text-slate-400">
            <IconDisk size={13} /> File Manager
            <span className="text-slate-600">/</span>
            <span className="text-slate-300">oxide/plugins</span>
          </span>
          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full border border-emerald-400/30 bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold text-emerald-300">
            <span className={`h-1.5 w-1.5 rounded-full bg-emerald-400 ${reduced ? "" : "pv-glow-breathe"}`} /> SFTP live
          </span>
        </div>

        {/* file rows */}
        <div className="divide-y divide-white/[0.05] font-mono text-[13px]">
          {[
            { name: "NTeleportation.cs", size: "84 KB", tint: "text-slate-300" },
            { name: "Kits.cs", size: "51 KB", tint: "text-slate-300" },
            { name: "Clans.cs", size: "63 KB", tint: "text-slate-300" },
          ].map((f) => (
            <div key={f.name} className="flex items-center gap-3 px-4 py-2.5">
              <IconCode size={15} className="shrink-0 text-brand-300" />
              <span className={`flex-1 ${f.tint}`}>{f.name}</span>
              <span className="text-slate-600">{f.size}</span>
              <IconCheck size={14} className="text-emerald-400" />
            </div>
          ))}

          {/* the uploading row */}
          <div className="px-4 py-3">
            <div className="flex items-center gap-3">
              <IconCode size={15} className="shrink-0 text-white" />
              <span className="flex-1 text-white">RaidableBases.cs</span>
              <span className="tabular-nums text-slate-400">{done ? "127 KB" : `${pct}%`}</span>
            </div>
            <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/[0.06]">
              <div
                className="h-full rounded-full transition-[width] duration-150"
                style={{ width: `${pct}%`, background: `linear-gradient(90deg, ${ACCENT}, ${CYAN})` }}
              />
            </div>
          </div>
        </div>

        {/* footer state */}
        <div className="flex items-center gap-3 border-t border-white/[0.07] bg-white/[0.02] px-4 py-3">
          {done ? (
            <>
              <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/30 bg-emerald-500/10 px-2.5 py-1 text-[11px] font-semibold text-emerald-300">
                <IconCheck size={12} /> Uploaded
