              <span className="font-mono text-[11px] text-slate-500">restart to load →</span>
              <span className="ml-auto inline-flex items-center gap-1.5 rounded-lg bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1.5 text-[11px] font-semibold text-white">
                <IconBolt size={12} /> Restart
              </span>
            </>
          ) : (
